<?php
declare(strict_types=1); require dirname(__DIR__).'/app/bootstrap.php';
$from=filter_input(INPUT_GET,'from',FILTER_VALIDATE_INT) ?: null; $to=filter_input(INPUT_GET,'to',FILTER_VALIDATE_INT) ?: null; $date=$_GET['date']??''; $people=max(1,min(20,(int)($_GET['people']??1)));
$sql="SELECT t.id,t.departure_at,t.arrival_at,t.price,t.currency,t.seats_total,t.vehicle_type,t.image_path,t.trip_class,t.vehicle_description,c.name company_name,o.name_ar origin_name,d.name_ar destination_name,(t.seats_total-COALESCE((SELECT SUM(b.passengers_count) FROM bookings b WHERE b.trip_id=t.id AND b.status='confirmed'),0)) seats_available FROM trips t JOIN companies c ON c.id=t.company_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id WHERE t.is_published=1 AND t.status='available' AND t.departure_at>=NOW()"; $args=[];
if($from){$sql.=" AND t.origin_city_id=?";$args[]=$from;} if($to){$sql.=" AND t.destination_city_id=?";$args[]=$to;} if($date && preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$sql.=" AND DATE(t.departure_at)=?";$args[]=$date;}
$sql.=" ORDER BY t.departure_at ASC LIMIT 100";
try{$q=Database::connection()->prepare($sql);$q->execute($args);$trips=$q->fetchAll();}catch(Throwable){$trips=[];}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الرحلات | أصل المتصدر</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="site-header"><a class="brand" href="/"><span class="brand-mark"><?php if(!empty($config['logo'])):?><img src="<?=e($config['logo'])?>" alt="شعار الموقع"><?php else:?>م<?php endif;?></span><b><?=e($config['name'])?></b></a><a class="btn btn-outline" href="/">الرئيسية</a></header><main class="section"><div class="section-heading"><div><span class="eyebrow">اختر وجهتك</span><h2>الرحلات المتاحة</h2></div><span class="muted"><?=count($trips)?> رحلة</span></div><?php if(!$trips):?><div class="empty-state">لا توجد رحلات مطابقة حالياً. جرّب تاريخاً أو وجهة أخرى.</div><?php else:?><div class="trip-grid"><?php foreach($trips as $t):?><article class="trip-card"><?php if(!empty($t['image_path'])):?><img class="trip-card-image" src="<?=e($t['image_path'])?>" alt="صورة الحافلة"><?php endif;?><div class="trip-card-top"><span class="trip-company"><?=e($t['company_name'])?></span><?php if(($t['trip_class']??'regular')==='vip'):?><span class="vip-badge">VIP</span><?php endif;?><span class="availability"><?=max(0,(int)$t['seats_available'])?> مقعد متاح</span></div><div class="route"><div><small>من</small><b><?=e($t['origin_name'])?></b></div><span class="route-arrow">←</span><div><small>إلى</small><b><?=e($t['destination_name'])?></b></div></div><div class="trip-meta"><span><?=e(date('d/m/Y H:i',strtotime($t['departure_at'])))?></span><strong><?=e(number_format((float)$t['price'],2))?> <?=e($t['currency'])?></strong></div><a class="btn btn-primary full" href="/trip.php?id=<?=(int)$t['id']?>">عرض التفاصيل والحجز</a></article><?php endforeach;?></div><?php endif;?></main><footer><span>© <?=date('Y')?> أصل المتصدر</span><a href="https://wa.me/<?=e($config['whatsapp'])?>">واتساب</a></footer></body></html>